/**
 * Per-100g nutrition reference for the recipe ingredient vocabulary (task #115).
 *
 * WHY THIS EXISTS
 * The 957 recipes in `recipes` were generated by an LLM — both the ingredient lists and
 * the macros. The macros were never derived from the ingredients, which is why a user on
 * Browse Meals saw lists that don't match the numbers. This table lets us do it properly:
 * assign a quantity to every ingredient, then COMPUTE the macros from those quantities.
 *
 * CONVENTIONS — read before adding entries
 * - Values are per 100 g EDIBLE PORTION, using standard food-composition figures
 *   (USDA FoodData Central / McCance & Widdowson conventions).
 * - Grains, pasta, pulses and oats are DRY/UNCOOKED weight, which is what a recipe
 *   ingredient line means ("60g basmati rice"). Anything meant as cooked weight has
 *   `cooked: true` and uses cooked values. Getting this wrong is a ~3x calorie error, so
 *   it is the single most important field here.
 * - Meat and fish are RAW.
 * - `confidence: 'low'` marks a value worth a second look. `recompute.ts` refuses to
 *   auto-apply any recipe containing a low-confidence ingredient — it goes to review.
 * - kcal is stored as published, NOT recomputed from the macros. Small Atwater
 *   discrepancies are normal in real composition data; a validator checks the gap.
 */

export type Food = {
  /** kcal per 100 g */
  kcal: number;
  /** grams per 100 g */
  protein: number;
  carbs: number;
  fat: number;
  /** True when the figures are for the cooked food (default: raw / dry). */
  cooked?: boolean;
  confidence?: 'low';
  note?: string;
};

/**
 * Keys are normalised food names (lowercase, quantity stripped). Matching is done by
 * `normaliseFood()` in parse-seeds.ts, longest-key-first with word boundaries — so
 * "butter beans" never matches "butter".
 */
