/**
 * Foods where published kcal legitimately disagrees with a naive Atwater sum:
 *  - high-fibre / high-water plants: published kcal excludes indigestible fibre,
 *    while 4 kcal/g over total carbohydrate counts it
 *  - mirin: ~8% ABV, and alcohol's 7 kcal/g isn't in the P/C/F sum at all
 * Exempting them is not hand-waving — it's why the check can stay strict elsewhere.
 */
const ATWATER_EXEMPT = new Set([
  'baby spinach', 'spinach', 'asparagus tips', 'chestnut mushrooms', 'mushrooms',
  'rocket', 'basil', 'lemon', 'lemon juice', 'lime', 'chilli flakes',
  'smoked paprika', 'cumin', 'cinnamon', 'garlic', 'ginger', 'coriander',
  'parsley', 'dill', 'mirin',
  // Dried herbs/spices and high-fibre plants — same fibre effect as above.
  'oregano', 'herbs', 'herbs de provence', 'fresh thyme', 'paprika', 'chives',
  'mint', 'chilli', 'jalapeño', 'sun-dried tomatoes', 'corn', 'nori',
  'dried wakame seaweed', 'capers', 'rehydrated soya mince', 'pomegranate seeds',
]);

/**
 * Sanity check: for calorie-dense foods, published kcal should track its own Atwater
 * sum. Catches a mistyped macro — the failure mode that would silently corrupt every
 * recipe using that ingredient.
 */
export function validateTable(): string[] {
  const problems: string[] = [];
  for (const [name, f] of Object.entries(FOODS)) {
    if (ATWATER_EXEMPT.has(name)) continue;
    const atwater = f.protein * 4 + f.carbs * 4 + f.fat * 9;
    if (f.kcal === 0 && atwater === 0) continue;
    if (f.kcal < 60) continue; // fibre/water dominate; ratio is meaningless here
    const delta = Math.abs(atwater - f.kcal) / Math.max(f.kcal, 1);
    if (delta > 0.15) {
      problems.push(
        `${name}: kcal ${f.kcal} vs Atwater ${atwater.toFixed(0)} (${(delta * 100).toFixed(0)}% apart)`,
      );
    }
  }
  return problems;
}
